//! Per-session outbound queue with bounded memory and configurable overflow policy.
//!
//! The queue has two lanes:
//!
//! * **control** — protocol replies generated by the broker (CONNACK, SUBACK, PUBACK, ...).
//!   They are always delivered first and never dropped by the overflow policy, but a hard cap
//!   protects against a peer that keeps sending requests without reading the replies.
//! * **publish** — application messages routed to the session, bounded by count and bytes.
//!   When full, the configured policy drops either the oldest queued message or the incoming one.
//!
//! The consumer can pause the publish lane (MQTT v5.0 Receive Maximum flow control) while still
//! draining control packets.

use crate::config::QueueFullPolicy;
use crate::protocol::{MqttPacket, PublishPacket};
use std::collections::VecDeque;
use std::sync::Mutex;
use std::time::Instant;
use tokio::sync::Notify;

/// A message routed to a session.
#[derive(Debug, Clone)]
pub struct Delivery {
    /// Message with QoS already downgraded to the subscription's granted QoS. The packet id is
    /// assigned by the transport when the message is sent.
    pub publish: PublishPacket,
    /// Absolute expiry derived from the Message Expiry Interval.
    pub expires_at: Option<Instant>,
    pub enqueued_at: Instant,
}

impl Delivery {
    pub fn new(publish: PublishPacket, expires_at: Option<Instant>) -> Self {
        Self {
            publish,
            expires_at,
            enqueued_at: Instant::now(),
        }
    }

    pub fn size(&self) -> usize {
        self.publish.topic.len() + self.publish.payload.len()
    }

    pub fn is_expired(&self, now: Instant) -> bool {
        self.expires_at.is_some_and(|t| t <= now)
    }
}

#[derive(Debug)]
pub enum Outbound {
    /// Protocol packet generated by the broker in response to the peer.
    Control(MqttPacket),
    /// Application message delivery.
    Publish(Delivery),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PushResult {
    Queued,
    /// The message was queued after discarding the oldest queued message(s).
    QueuedDroppedOldest,
    /// The incoming message was discarded.
    Dropped,
    /// The queue is closed.
    Closed,
}

#[derive(Debug, Clone, Copy)]
pub struct QueueLimits {
    pub max_messages: usize,
    pub max_bytes: usize,
    pub policy: QueueFullPolicy,
    /// Control packets allowed to pile up before the peer is considered unresponsive.
    pub max_control: usize,
}

impl Default for QueueLimits {
    fn default() -> Self {
        Self {
            max_messages: 5000,
            max_bytes: 8 * 1024 * 1024,
            policy: QueueFullPolicy::DropOldest,
            max_control: 4096,
        }
    }
}

#[derive(Debug, Default)]
struct State {
    control: VecDeque<MqttPacket>,
    publish: VecDeque<Delivery>,
    publish_bytes: usize,
    dropped: u64,
    closed: bool,
}

#[derive(Debug)]
pub struct OutboundQueue {
    state: Mutex<State>,
    notify: Notify,
    limits: QueueLimits,
}

impl OutboundQueue {
    pub fn new(limits: QueueLimits) -> Self {
        Self {
            state: Mutex::new(State::default()),
            notify: Notify::new(),
            limits,
        }
    }

    pub fn limits(&self) -> QueueLimits {
        self.limits
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// Queues a control packet. Returns false when the queue is closed or the control backlog
    /// exceeded its cap (the caller should then drop the connection).
    pub fn push_control(&self, packet: MqttPacket) -> bool {
        let mut st = self.lock();
        if st.closed || st.control.len() >= self.limits.max_control {
            return false;
        }
        st.control.push_back(packet);
        drop(st);
        self.notify.notify_one();
        true
    }

    /// Queues an application message, applying the overflow policy.
    pub fn push_publish(&self, delivery: Delivery) -> PushResult {
        let size = delivery.size();
        let mut st = self.lock();
        if st.closed {
            return PushResult::Closed;
        }
        let limits = self.limits;
        let over = |st: &State| {
            st.publish.len() >= limits.max_messages || st.publish_bytes + size > limits.max_bytes
        };
        let mut result = PushResult::Queued;
        if over(&st) {
            if limits.policy == QueueFullPolicy::DropNewest || size > limits.max_bytes {
                st.dropped += 1;
                return PushResult::Dropped;
            }
            while over(&st) {
                let Some(old) = st.publish.pop_front() else {
                    break;
                };
                st.publish_bytes -= old.size();
                st.dropped += 1;
                result = PushResult::QueuedDroppedOldest;
            }
        }
        st.publish_bytes += size;
        st.publish.push_back(delivery);
        drop(st);
        self.notify.notify_one();
        result
    }

    /// Removes the next item without waiting. Control packets always come first; publishes are
    /// only returned when `allow_publish` is true.
    pub fn try_pop(&self, allow_publish: bool) -> Option<Outbound> {
        let mut st = self.lock();
        if let Some(p) = st.control.pop_front() {
            return Some(Outbound::Control(p));
        }
        if !allow_publish {
            return None;
        }
        let d = st.publish.pop_front()?;
        st.publish_bytes -= d.size();
        Some(Outbound::Publish(d))
    }

    /// Waits for the next item. `allow_publish` is re-evaluated after every wake-up, so the
    /// consumer can pause the publish lane and resume it with [`OutboundQueue::wake`].
    /// Returns `None` once the queue is closed and has nothing deliverable left.
    pub async fn pop(&self, allow_publish: impl Fn() -> bool) -> Option<Outbound> {
        loop {
            let notified = self.notify.notified();
            tokio::pin!(notified);
            notified.as_mut().enable();
            let allow = allow_publish();
            if let Some(item) = self.try_pop(allow) {
                return Some(item);
            }
            {
                let st = self.lock();
                if st.closed && (st.control.is_empty() && (st.publish.is_empty() || !allow)) {
                    return None;
                }
            }
            notified.await;
        }
    }

    /// Re-queues a publish at the front (used when a transport could not deliver it yet).
    pub fn push_front_publish(&self, delivery: Delivery) {
        let mut st = self.lock();
        st.publish_bytes += delivery.size();
        st.publish.push_front(delivery);
        drop(st);
        self.notify.notify_one();
    }

    /// Stops accepting new items; queued items can still be drained with `pop`.
    pub fn close(&self) {
        self.lock().closed = true;
        self.notify.notify_waiters();
        self.notify.notify_one();
    }

    /// Wakes the consumer without queuing anything (e.g. after inflight capacity frees up).
    pub fn wake(&self) {
        self.notify.notify_one();
    }

    pub fn is_closed(&self) -> bool {
        self.lock().closed
    }

    pub fn queued_messages(&self) -> usize {
        self.lock().publish.len()
    }

    pub fn queued_bytes(&self) -> usize {
        self.lock().publish_bytes
    }

    pub fn dropped(&self) -> u64 {
        self.lock().dropped
    }

    /// Drops pending control packets (they belong to a connection that no longer exists).
    pub fn clear_control(&self) {
        self.lock().control.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use bytes::Bytes;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;

    fn delivery(n: usize) -> Delivery {
        Delivery::new(
            PublishPacket::new("t", Bytes::from(format!("msg_{n}"))),
            None,
        )
    }

    fn payload(item: Outbound) -> String {
        match item {
            Outbound::Publish(d) => String::from_utf8(d.publish.payload.to_vec()).unwrap(),
            Outbound::Control(p) => format!("{p:?}"),
        }
    }

    fn limits(max_messages: usize, policy: QueueFullPolicy) -> QueueLimits {
        QueueLimits {
            max_messages,
            max_bytes: 1 << 20,
            policy,
            max_control: 8,
        }
    }

    #[test]
    fn drop_oldest_keeps_most_recent_messages() {
        let q = OutboundQueue::new(limits(5, QueueFullPolicy::DropOldest));
        for i in 1..=5 {
            assert_eq!(q.push_publish(delivery(i)), PushResult::Queued);
        }
        assert_eq!(q.push_publish(delivery(6)), PushResult::QueuedDroppedOldest);
        assert_eq!(q.queued_messages(), 5);
        assert_eq!(q.dropped(), 1);
        assert_eq!(payload(q.try_pop(true).unwrap()), "msg_2");
    }

    #[test]
    fn drop_newest_rejects_incoming_messages() {
        let q = OutboundQueue::new(limits(3, QueueFullPolicy::DropNewest));
        for i in 1..=3 {
            q.push_publish(delivery(i));
        }
        assert_eq!(q.push_publish(delivery(4)), PushResult::Dropped);
        let all: Vec<String> = std::iter::from_fn(|| q.try_pop(true))
            .map(payload)
            .collect();
        assert_eq!(all, vec!["msg_1", "msg_2", "msg_3"]);
    }

    #[test]
    fn byte_limit_is_enforced() {
        let q = OutboundQueue::new(QueueLimits {
            max_messages: 100,
            max_bytes: 20,
            policy: QueueFullPolicy::DropOldest,
            max_control: 8,
        });
        // Each delivery is 1 (topic) + 5 (payload) = 6 bytes.
        for i in 1..=3 {
            q.push_publish(delivery(i));
        }
        assert_eq!(q.queued_bytes(), 18);
        assert_eq!(q.push_publish(delivery(4)), PushResult::QueuedDroppedOldest);
        assert_eq!(q.queued_bytes(), 18);
        // A single message larger than the whole budget is dropped without evicting others.
        let huge = Delivery::new(PublishPacket::new("t", Bytes::from(vec![0u8; 64])), None);
        assert_eq!(q.push_publish(huge), PushResult::Dropped);
        assert_eq!(q.queued_messages(), 3);
    }

    #[test]
    fn control_lane_has_priority_and_is_capped() {
        let q = OutboundQueue::new(limits(1, QueueFullPolicy::DropNewest));
        q.push_publish(delivery(1));
        for _ in 0..8 {
            assert!(q.push_control(MqttPacket::PingResp));
        }
        assert!(!q.push_control(MqttPacket::PingResp));
        assert!(matches!(q.try_pop(true), Some(Outbound::Control(_))));
        // With the publish lane paused only control packets come out.
        for _ in 0..7 {
            assert!(matches!(q.try_pop(false), Some(Outbound::Control(_))));
        }
        assert!(q.try_pop(false).is_none());
        assert_eq!(payload(q.try_pop(true).unwrap()), "msg_1");
    }

    #[tokio::test]
    async fn pop_waits_resumes_after_wake_and_close_drains() {
        let q = Arc::new(OutboundQueue::new(QueueLimits::default()));
        let gate = Arc::new(AtomicBool::new(false));
        q.push_publish(delivery(7));

        let (q2, g2) = (q.clone(), gate.clone());
        let waiter =
            tokio::spawn(async move { q2.pop(|| g2.load(Ordering::SeqCst)).await.map(payload) });
        tokio::task::yield_now().await;
        assert!(!waiter.is_finished());
        gate.store(true, Ordering::SeqCst);
        q.wake();
        assert_eq!(waiter.await.unwrap().as_deref(), Some("msg_7"));

        q.push_publish(delivery(8));
        q.close();
        assert_eq!(q.push_publish(delivery(9)), PushResult::Closed);
        assert_eq!(q.pop(|| true).await.map(payload).as_deref(), Some("msg_8"));
        assert!(q.pop(|| true).await.is_none());
    }
}
